const item = $input.first().json;
const displayName = String(item?.metadata?.displayName ?? '');
if (!displayName.toLowerCase().includes('twitch')) throw new Error('Twitch branch received a different provider.');
if (typeof item.credentialKey !== 'string' || item.credentialKey.length === 0) throw new Error('Twitch item has no public credentialKey.');
return [{ json: { credentialKey: item.credentialKey, secretNames: ['accessToken'], providerDisplayName: displayName } }];

const item = $input.first().json;
const displayName = String(item?.metadata?.displayName ?? '');
const normalizedName = displayName.replace(/[\s_-]+/g, '').toLowerCase();
if (!normalizedName.includes('openai')) throw new Error('OpenAI branch received a different provider.');
if (typeof item.credentialKey !== 'string' || item.credentialKey.length === 0) throw new Error('OpenAI item has no public credentialKey.');
return [{ json: { credentialKey: item.credentialKey, secretNames: ['apiKey'], providerDisplayName: displayName } }];

const selected = $input.first().json;
if (typeof selected?.credentialKey !== 'string' || selected.credentialKey.length === 0) throw new Error('Selected Credential has no public credentialKey.');
if (!Array.isArray(selected?.secretNames) || selected.secretNames.length === 0) throw new Error('Selected Credential has no configured Secret fields.');
return [{ json: selected }];

const data = $input.first().json.data;
const selected = $('Prepare Selected Credential').first().json;
if (!data || data.credentialKey !== selected.credentialKey || data.lifecycleState !== 'active' || typeof data.providerKey !== 'string' || !data.secrets || typeof data.secrets !== 'object' || Array.isArray(data.secrets)) throw new Error('Resolve response did not contain a valid active Credential.');
const resolvedNames = Object.keys(data.secrets);
if (resolvedNames.length !== selected.secretNames.length || resolvedNames.some((name) => !selected.secretNames.includes(name)) || selected.secretNames.some((name) => typeof data.secrets[name] !== 'string')) throw new Error('Resolve response did not contain exactly the requested Secret fields.');
return [{ json: { status: 'success', credentialKey: selected.credentialKey, providerDisplayName: selected.providerDisplayName, resolvedSecretNames: resolvedNames, timestamp: new Date().toISOString() } }];
